import {useEffect,useMemo,useState} from 'react';
import {CalendarDays,Clock3,Plus,RefreshCw,Settings2,UsersRound,X} from 'lucide-react';
import {createAppointmentType,createBookingLink,createScheduledAppointment,createSchedulingAvailability,createWaitlistEntry,getCalendarSyncStatus,getTeamAccess,listAppointmentTypes,listPracticeCalendar,listScheduledAppointments,listSchedulingAvailability,listWaitlist,prepareCalendarConnection,updateScheduledAppointment} from '../../lib/practiceOperationsApi';
import {listExternalClients} from '../../lib/fiteatsyConsultantsApi';
import {buildWhatsAppUrl} from '../../lib/whatsappLaunch.mjs';

const VIEWS=['AGENDA','DAY','WEEK','MONTH'];
const EMPTY_TYPE={name:'',description:'',duration_minutes:45,buffer_before_minutes:0,buffer_after_minutes:0,location_type:'ONLINE',location_details:''};
const EMPTY_RULE={weekday:1,start_time:'09:00',end_time:'17:00',timezone:Intl.DateTimeFormat().resolvedOptions().timeZone||'UTC'};

export function ExternalCalendarWorkspace({clients:providedClients=[]}){
  const [clients,setClients]=useState(providedClients);
  const [view,setView]=useState('AGENDA');const [page,setPage]=useState({items:[]});const [types,setTypes]=useState([]);const [rules,setRules]=useState([]);const [appointments,setAppointments]=useState([]);const [waitlist,setWaitlist]=useState([]);const [loading,setLoading]=useState(true);const [error,setError]=useState('');const [modal,setModal]=useState(null);const [shareUrl,setShareUrl]=useState('');const [shareClient,setShareClient]=useState(null);
  const [calendarScope,setCalendarScope]=useState('MY');const [teamAccess,setTeamAccess]=useState({permissions:[]});
  const [calendarSync,setCalendarSync]=useState({providers:[],busyBlocks:[],schedulingAuthority:'P13_INTERNAL'});
  async function load(){setLoading(true);setError('');try{const [calendar,kinds,availability,bookings,waiting,clientPage,sync]=await Promise.all([listPracticeCalendar({view}),listAppointmentTypes(),listSchedulingAvailability(),listScheduledAppointments(),listWaitlist(),providedClients.length?Promise.resolve(null):listExternalClients({limit:100}),getCalendarSyncStatus().catch(()=>({providers:[{provider:'GOOGLE',calendarProvider:'NOT_CONFIGURED'},{provider:'MICROSOFT',calendarProvider:'NOT_CONFIGURED'}],busyBlocks:[],schedulingAuthority:'P13_INTERNAL'}))]);setPage(calendar);setTypes(kinds.items||[]);setRules(availability.items||[]);setAppointments(bookings.items||[]);setWaitlist(waiting.items||[]);setCalendarSync(sync);if(clientPage)setClients((clientPage.clients||[]).map(client=>({id:client.id,displayName:client.displayName||client.fullName||[client.firstName,client.lastName].filter(Boolean).join(' ')||'Client',mobile:client.mobile||client.phone||''})));}catch(reason){setError(reason.message||'Calendar could not load.')}finally{setLoading(false)}}
  useEffect(()=>{void load()},[view]);
  useEffect(()=>{getTeamAccess().then(setTeamAccess).catch(()=>setTeamAccess({permissions:[]}))},[]);
  const metrics=useMemo(()=>[['Upcoming',appointments.filter(item=>['BOOKED','CONFIRMED'].includes(item.status)&&new Date(item.starts_at)>=new Date()).length,CalendarDays],['Appointment types',types.length,Settings2],['Availability rules',rules.filter(item=>item.active).length,Clock3],['Waitlist',waitlist.filter(item=>item.status==='WAITING').length,UsersRound]],[appointments,rules,types,waitlist]);
  async function save(event){event.preventDefault();setError('');try{if(modal.kind==='type')await createAppointmentType({...modal.form,duration_minutes:Number(modal.form.duration_minutes),buffer_before_minutes:Number(modal.form.buffer_before_minutes),buffer_after_minutes:Number(modal.form.buffer_after_minutes),description:modal.form.description||null,location_details:modal.form.location_details||null});if(modal.kind==='rule')await createSchedulingAvailability(modal.form);if(modal.kind==='booking')await createScheduledAppointment({...modal.form,starts_at:new Date(modal.form.starts_at).toISOString()});if(modal.kind==='waitlist')await createWaitlistEntry({...modal.form,preferred_from:modal.form.preferred_from?new Date(modal.form.preferred_from).toISOString():null,preferred_until:modal.form.preferred_until?new Date(modal.form.preferred_until).toISOString():null,notes:modal.form.notes||null});if(modal.kind==='link'){const result=await createBookingLink({...modal.form,label:modal.form.label||null});setShareUrl(`${window.location.origin}/book/${result.token}`);setShareClient(clients.find(client=>client.id===modal.form.client_id)||null);}setModal(null);await load();}catch(reason){setError(reason.message||'Scheduling change could not be saved.')}}
  async function status(item,next){try{await updateScheduledAppointment(item.id,{status:next,cancellation_reason:null});await load();}catch(reason){setError(reason.message||'Appointment could not be updated.')}}
  const bookingForm={client_id:clients[0]?.id||'',appointment_type_id:types[0]?.id||'',starts_at:''};
  return <div className="space-y-6 pb-24 lg:pb-8"><header className="flex flex-col justify-between gap-4 rounded-[28px] bg-slate-950 p-6 text-white sm:flex-row sm:items-end sm:p-8"><div><p className="text-xs font-bold uppercase tracking-[.18em] text-blue-300">Practice scheduling</p><h2 className="mt-2 text-3xl font-bold tracking-tight">Calendar &amp; booking</h2><p className="mt-2 text-sm text-slate-300">Manage availability, appointments, attendance, self-booking, and waitlist demand.</p></div><div className="flex flex-wrap gap-2"><button onClick={()=>setModal({kind:'type',form:EMPTY_TYPE})} className="min-h-11 rounded-xl border border-white/20 px-4 text-sm font-bold">Appointment type</button><button disabled={!types.length||!clients.length} onClick={()=>setModal({kind:'link',form:{client_id:clients[0]?.id||'',appointment_type_id:types[0]?.id||'',label:''}})} className="min-h-11 rounded-xl border border-white/20 px-4 text-sm font-bold disabled:opacity-40">Self-booking link</button><button disabled={!types.length||!clients.length} onClick={()=>setModal({kind:'booking',form:bookingForm})} className="min-h-11 rounded-xl bg-white px-4 text-sm font-bold text-slate-950 disabled:opacity-40"><Plus className="mr-2 inline" size={16}/>Book</button></div></header>
    {shareUrl&&<div role="status" className="rounded-2xl border border-emerald-200 bg-emerald-50 p-4 text-sm text-emerald-900"><p className="font-bold">Client-bound self-booking link created</p><div className="mt-2 flex flex-col gap-2 sm:flex-row"><input readOnly value={shareUrl} aria-label="Self-booking link" className="min-h-11 flex-1 rounded-xl border border-emerald-200 bg-white px-3"/><a href={buildWhatsAppUrl({phone:shareClient?.mobile,message:`Hi ${shareClient?.displayName||'there'}, please use this secure link to book your appointment: ${shareUrl}`})} target="_blank" rel="noreferrer" className="inline-flex min-h-11 items-center justify-center rounded-xl bg-emerald-800 px-4 font-bold text-white">Share via WhatsApp</a><button onClick={()=>navigator.clipboard.writeText(shareUrl)} className="min-h-11 rounded-xl border border-emerald-300 bg-white px-4 font-bold">Copy link</button></div></div>}
    {error&&<div role="alert" className="rounded-2xl border border-red-200 bg-red-50 p-4 text-sm text-red-800">{error}<button onClick={load} className="ml-3 font-bold"><RefreshCw className="inline" size={15}/> Retry</button></div>}
    <section className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{metrics.map(([label,value,Icon])=><article key={label} className="rounded-3xl border border-slate-200 bg-white p-5"><Icon className="text-blue-700"/><p className="mt-4 text-3xl font-bold">{loading?'—':value}</p><p className="mt-1 text-sm text-slate-600">{label}</p></article>)}</section>
    <section aria-labelledby="calendar-sync-title" className="rounded-3xl border border-slate-200 bg-white p-5"><div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-start"><div><p className="text-xs font-bold uppercase tracking-[.16em] text-blue-700">External availability</p><h3 id="calendar-sync-title" className="mt-1 text-xl font-bold">Calendar sync</h3><p className="mt-2 max-w-2xl text-sm text-slate-600">Google Calendar and Outlook can contribute private busy windows. Zestiva scheduling remains authoritative; external event names are never shown to clients.</p></div><span className="w-fit rounded-full bg-slate-100 px-3 py-1 text-xs font-bold">P13 internal authority</span></div><div className="mt-5 grid gap-3 md:grid-cols-2">{calendarSync.providers.map(item=><article key={item.provider} className="rounded-2xl border border-slate-200 p-4"><div className="flex items-center justify-between gap-3"><div><h4 className="font-bold">{item.provider==='GOOGLE'?'Google Calendar':'Microsoft Outlook'}</h4><p className="mt-1 text-xs text-slate-500">CALENDAR_PROVIDER: {item.calendarProvider}</p></div><button onClick={async()=>{const result=await prepareCalendarConnection(item.provider);setError(result.calendarProvider==='NOT_CONFIGURED'?`${item.provider} provider credentials are not configured for this environment.`:'')}} className="min-h-11 rounded-xl border px-3 text-sm font-bold">Configure</button></div></article>)}</div>{calendarSync.busyBlocks.length>0&&<div className="mt-5"><h4 className="text-sm font-bold">External busy time</h4><div className="mt-2 grid gap-2 md:grid-cols-2">{calendarSync.busyBlocks.map(item=><div key={item.id} className="rounded-xl bg-slate-100 p-3 text-sm"><strong>Busy</strong><span className="ml-2 text-slate-600">{new Date(item.starts_at).toLocaleString()} – {new Date(item.ends_at).toLocaleTimeString()}</span></div>)}</div></div>}</section>
    <section className="rounded-3xl border border-slate-200 bg-white p-5"><div className="mb-4 flex gap-2" aria-label="Calendar authority scope"><button onClick={()=>setCalendarScope('MY')} aria-pressed={calendarScope==='MY'} className={`min-h-11 rounded-xl px-4 text-sm font-semibold ${calendarScope==='MY'?'bg-blue-700 text-white':'border'}`}>My Calendar</button>{teamAccess.permissions?.includes('CALENDAR_MANAGE')&&<button onClick={()=>setCalendarScope('TEAM')} aria-pressed={calendarScope==='TEAM'} className={`min-h-11 rounded-xl px-4 text-sm font-semibold ${calendarScope==='TEAM'?'bg-blue-700 text-white':'border'}`}>Team Calendar</button>}</div><p className="mb-4 text-xs text-slate-500">{calendarScope==='TEAM'?'Practice scheduling availability is shown without private professional detail.':'Your authorised scheduling view.'}</p><div className="flex flex-col justify-between gap-3 sm:flex-row sm:items-center"><nav aria-label="Calendar view" className="flex gap-2 overflow-x-auto">{VIEWS.map(item=><button key={item} onClick={()=>setView(item)} aria-current={view===item?'page':undefined} className={`min-h-11 shrink-0 rounded-full px-4 text-sm font-bold ${view===item?'bg-slate-950 text-white':'border bg-white text-slate-700'}`}>{item[0]+item.slice(1).toLowerCase()}</button>)}</nav><div className="flex gap-2"><button onClick={()=>setModal({kind:'rule',form:EMPTY_RULE})} className="min-h-11 rounded-xl border px-3 text-xs font-bold">Add availability</button><button disabled={!types.length||!clients.length} onClick={()=>setModal({kind:'waitlist',form:{client_id:clients[0]?.id||'',appointment_type_id:types[0]?.id||'',preferred_from:'',preferred_until:'',notes:''}})} className="min-h-11 rounded-xl border px-3 text-xs font-bold disabled:opacity-40">Add waitlist</button></div></div>
      {loading?<div role="status" className="mt-5 min-h-40 animate-pulse rounded-2xl bg-slate-50 p-6">Loading calendar…</div>:page.items.length?<div className="mt-5 grid gap-3 md:grid-cols-2 xl:grid-cols-3">{page.items.map(item=><article key={`${item.source_type}-${item.id}`} className="rounded-2xl border border-slate-200 p-5"><span className="text-xs font-bold uppercase tracking-wider text-blue-700">{item.source_type.replaceAll('_',' ')}</span><h3 className="mt-2 font-bold">{item.title}</h3><p className="mt-2 text-sm text-slate-500">{new Date(item.starts_at).toLocaleString()}</p><div className="mt-4 flex items-center justify-between"><span className="inline-flex rounded-full bg-slate-100 px-2.5 py-1 text-xs font-semibold">{item.status.replaceAll('_',' ')}</span>{item.source_type==='APPOINTMENT'&&['BOOKED','CONFIRMED'].includes(item.status)&&<span className="flex gap-1"><button onClick={()=>status(item,'COMPLETED')} className="min-h-9 rounded-lg bg-emerald-50 px-2 text-xs font-bold text-emerald-700">Attended</button><button onClick={()=>status(item,'NO_SHOW')} className="min-h-9 rounded-lg bg-amber-50 px-2 text-xs font-bold text-amber-800">No-show</button></span>}</div></article>)}</div>:<div className="mt-5 rounded-3xl border border-dashed border-slate-300 px-6 py-16 text-center"><CalendarDays className="mx-auto text-blue-700"/><h3 className="mt-4 text-lg font-bold">No scheduled work in this view</h3><p className="mt-2 text-sm text-slate-500">Appointments, consultations, follow-ups, and tasks will appear here.</p></div>}
    </section>{modal&&<SchedulingModal modal={modal} setModal={setModal} onClose={()=>setModal(null)} onSubmit={save} clients={clients} types={types}/>}</div>;
}

function SchedulingModal({modal,setModal,onClose,onSubmit,clients,types}){const f=modal.form;const set=(key,value)=>setModal({...modal,form:{...f,[key]:value}});const title={type:'Create appointment type',rule:'Add weekly availability',booking:'Book appointment',waitlist:'Add to waitlist',link:'Create self-booking link'}[modal.kind];return <div className="fixed inset-0 z-[80] flex items-end bg-slate-950/50 sm:items-center sm:justify-center sm:p-4"><form onSubmit={onSubmit} role="dialog" aria-modal="true" className="max-h-[92dvh] w-full overflow-y-auto rounded-t-3xl bg-white p-5 sm:max-w-xl sm:rounded-3xl"><div className="flex items-center justify-between"><h3 className="text-xl font-bold">{title}</h3><button type="button" onClick={onClose} aria-label="Close" className="grid h-11 w-11 place-items-center rounded-xl border"><X size={18}/></button></div><div className="mt-5 grid gap-4">{modal.kind==='type'&&<><Field label="Name"><input required value={f.name} onChange={e=>set('name',e.target.value)}/></Field><Field label="Description"><textarea value={f.description} onChange={e=>set('description',e.target.value)}/></Field><div className="grid gap-3 sm:grid-cols-3"><Field label="Duration"><input type="number" min="5" max="480" value={f.duration_minutes} onChange={e=>set('duration_minutes',e.target.value)}/></Field><Field label="Before buffer"><input type="number" min="0" value={f.buffer_before_minutes} onChange={e=>set('buffer_before_minutes',e.target.value)}/></Field><Field label="After buffer"><input type="number" min="0" value={f.buffer_after_minutes} onChange={e=>set('buffer_after_minutes',e.target.value)}/></Field></div><Field label="Location"><select value={f.location_type} onChange={e=>set('location_type',e.target.value)}><option value="ONLINE">Online</option><option value="IN_PERSON">In person</option><option value="PHONE">Phone</option><option value="OTHER">Other</option></select></Field><Field label="Location details"><input value={f.location_details} onChange={e=>set('location_details',e.target.value)}/></Field></>}{modal.kind==='rule'&&<><Field label="Weekday"><select value={f.weekday} onChange={e=>set('weekday',Number(e.target.value))}>{['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'].map((day,index)=><option key={day} value={index}>{day}</option>)}</select></Field><div className="grid grid-cols-2 gap-3"><Field label="Starts"><input type="time" required value={f.start_time} onChange={e=>set('start_time',e.target.value)}/></Field><Field label="Ends"><input type="time" required value={f.end_time} onChange={e=>set('end_time',e.target.value)}/></Field></div><Field label="Timezone"><input required value={f.timezone} onChange={e=>set('timezone',e.target.value)}/></Field></>}{['booking','waitlist','link'].includes(modal.kind)&&<><Field label="Client"><select required value={f.client_id} onChange={e=>set('client_id',e.target.value)}>{clients.map(client=><option key={client.id} value={client.id}>{client.displayName}</option>)}</select></Field><Field label="Appointment type"><select required value={f.appointment_type_id} onChange={e=>set('appointment_type_id',e.target.value)}>{types.map(type=><option key={type.id} value={type.id}>{type.name}</option>)}</select></Field></>}{modal.kind==='link'&&<Field label="Link label"><input value={f.label} placeholder="e.g. Book your follow-up" onChange={e=>set('label',e.target.value)}/></Field>}{modal.kind==='booking'&&<Field label="Date and time"><input required type="datetime-local" value={f.starts_at} onChange={e=>set('starts_at',e.target.value)}/></Field>}{modal.kind==='waitlist'&&<><div className="grid grid-cols-2 gap-3"><Field label="Preferred from"><input type="datetime-local" value={f.preferred_from} onChange={e=>set('preferred_from',e.target.value)}/></Field><Field label="Preferred until"><input type="datetime-local" value={f.preferred_until} onChange={e=>set('preferred_until',e.target.value)}/></Field></div><Field label="Notes"><textarea value={f.notes} onChange={e=>set('notes',e.target.value)}/></Field></>}</div><div className="mt-6 flex justify-end gap-2"><button type="button" onClick={onClose} className="min-h-11 rounded-xl border px-4 font-semibold">Cancel</button><button className="min-h-11 rounded-xl bg-slate-950 px-4 font-semibold text-white">Save</button></div></form></div>}
function Field({label,children}){return <label className="block text-sm font-semibold text-slate-700">{label}<span className="mt-2 block [&>*]:min-h-11 [&>*]:w-full [&>*]:rounded-xl [&>*]:border [&>*]:border-slate-200 [&>*]:p-3">{children}</span></label>}
